local function resolve(q,root,forceReturn,screenProgress)
 local targets,notes={},{}
 state.resolved=0 state.unresolved=0 state.searchHints=0
 state.numberedKnown=0 state.numberedExpected=0
 local tasks=q:FindFirstChild("Tasks")
