  model=model,humanoid=humanoid,root=root,track=track,
  name=profile.name or model.Name,hits=hits,index=1,
  expires=os.clock()+math.clamp((hits[#hits]-track.TimePosition)/math.max(track.Speed,0.1)+1,3,18)
