    if not G.VeyraConfig or not G.VeyraConfig.set then return end
    G.VeyraConfig.patch("parry", {
        selfImproving = {
            lead = state.lead,
            grantLag = state.grantLag,
            parryWindow = state.parryWindow,
            calibrated = state.calibrated,
        }
    })
end

