   end
  end
  table.sort(chainCands,function(a,b) return a.remaining<b.remaining end)
  local n=#chainCands
  local assign={} -- "parry" or "roll" for each candidate
  local i=1
  while i<=n do
   local entry=chainCands[i]
   local impactAt=now+entry.remaining
